import { app, page, route, query, action, api } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/auth/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/auth/SignupPage" with { type: "ref" };
import { FolderPage } from "./src/pages/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/pages/LogsPage" with { type: "ref" };
import { SharePage } from "./src/pages/SharePage" with { type: "ref" };
import { getFolderContents, getAccessLogs } from "./src/queries" with { type: "ref" };
import { createFolder, createShareLink } from "./src/actions" with { type: "ref" };
import { downloadFile, uploadFile } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp File Management System",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    // Routes and Pages
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage)),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    // Queries
    query(getFolderContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "ShareLink", "File"] }),

    // Actions
    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    // API Endpoints
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "AccessLog", "File"], auth: false }),
    api("POST", "/api/upload", uploadFile, { entities: ["File", "Folder"], auth: true }),
  ],
});

import { HttpError } from "wasp/server";

export const getFolderContents = async (
  args: { folderId: string | number | null | undefined },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const userId = context.user.id;
  const folderId = args.folderId ? Number(args.folderId) : null;

  let currentFolder = null;
  const breadcrumbs = [];

  if (folderId !== null) {
    currentFolder = await context.entities.Folder.findUnique({
      where: { id: folderId },
    });

    if (!currentFolder || currentFolder.userId !== userId) {
      throw new HttpError(404, "Folder not found");
    }

    // Build breadcrumbs
    let current = currentFolder;
    breadcrumbs.unshift(current);
    while (current.parentId) {
      const parent = await context.entities.Folder.findUnique({
        where: { id: current.parentId },
      });
      if (parent && parent.userId === userId) {
        breadcrumbs.unshift(parent);
        current = parent;
      } else {
        break;
      }
    }
  }

  const folders = await context.entities.Folder.findMany({
    where: {
      userId,
      parentId: folderId,
    },
    orderBy: { name: "asc" },
  });

  const files = await context.entities.File.findMany({
    where: {
      userId,
      folderId,
    },
    include: {
      shareLinks: true,
    },
    orderBy: { name: "asc" },
  });

  return {
    currentFolder,
    breadcrumbs,
    folders,
    files,
  };
};

export const getAccessLogs = async (args: void, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  return context.entities.AccessLog.findMany({
    where: {
      shareLink: {
        file: {
          userId: context.user.id,
        },
      },
    },
    include: {
      shareLink: {
        include: {
          file: true,
        },
      },
    },
    orderBy: {
      accessedAt: "desc",
    },
  });
};

import { HttpError } from "wasp/server";

export const createFolder = async (
  args: { name: string; parentId: string | number | null | undefined },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const userId = context.user.id;
  const parentId = args.parentId ? Number(args.parentId) : null;

  if (parentId !== null) {
    const parent = await context.entities.Folder.findUnique({
      where: { id: parentId },
    });
    if (!parent || parent.userId !== userId) {
      throw new HttpError(404, "Parent folder not found");
    }
  }

  return context.entities.Folder.create({
    data: {
      name: args.name,
      parentId,
      userId,
    },
  });
};

export const createShareLink = async (
  args: { fileId: number; password?: string; expiresInMinutes?: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const userId = context.user.id;
  const file = await context.entities.File.findUnique({
    where: { id: args.fileId },
  });

  if (!file || file.userId !== userId) {
    throw new HttpError(404, "File not found");
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes && args.expiresInMinutes > 0) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  return context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt,
    },
  });
};

import multer from "multer";
import fs from "fs";
import path from "path";
import { Request, Response } from "express";

const uploadDir = "/home/user/app/uploads/";
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + "-" + file.originalname);
  },
});

const upload = multer({ storage }).single("file");

export const uploadFile = (req: any, res: any, context: any) => {
  if (!context.user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  upload(req, res, async (err: any) => {
    if (err) {
      return res.status(500).json({ error: "Failed to upload file" });
    }

    if (!req.file) {
      return res.status(400).json({ error: "No file uploaded" });
    }

    try {
      const folderId = req.body.folderId ? Number(req.body.folderId) : null;
      const userId = context.user.id;

      if (folderId !== null) {
        const folder = await context.entities.Folder.findUnique({
          where: { id: folderId },
        });
        if (!folder || folder.userId !== userId) {
          return res.status(404).json({ error: "Folder not found" });
        }
      }

      const newFile = await context.entities.File.create({
        data: {
          name: req.file.originalname,
          path: req.file.path,
          size: req.file.size,
          mimeType: req.file.mimetype || "application/octet-stream",
          folderId,
          userId,
        },
      });

      return res.json(newFile);
    } catch (dbErr) {
      console.error(dbErr);
      return res.status(500).json({ error: "Database error" });
    }
  });
};

export const downloadFile = async (req: Request, res: Response, context: any) => {
  const { linkId } = req.params;
  const password = req.query.password as string | undefined;

  try {
    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: {
        file: true,
      },
    });

    if (!shareLink) {
      return res.status(404).json({ error: "Sharing link not found" });
    }

    // Check expiration
    if (shareLink.expiresAt && new Date(shareLink.expiresAt) < new Date()) {
      return res.status(410).json({ error: "Sharing link has expired" });
    }

    // Check password
    if (shareLink.password && shareLink.password !== password) {
      return res.status(403).json({ error: "Incorrect password" });
    }

    const file = shareLink.file;
    if (!fs.existsSync(file.path)) {
      return res.status(404).json({ error: "Physical file not found on server" });
    }

    // Log successful download
    const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress || "unknown";
    const userAgent = req.headers["user-agent"] || "unknown";

    await context.entities.AccessLog.create({
      data: {
        shareLinkId: shareLink.id,
        ipAddress,
        userAgent,
        fileName: file.name,
      },
    });

    // Send file
    return res.download(file.path, file.name);
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: "Server error during file download" });
  }
};

